import re
prev={}
cur={}
def parse(fn):
    d={}; k=None
    for line in open(fn,errors='replace'):
        m=re.match(r'===== (PMC\d+) =====', line.strip())
        if m: k=m.group(1); d[k]=[]
        elif k and line.strip(): d[k].append(line)
    return d
prev=parse('full_extract.txt')
cur=parse('final_extract.txt')
prev_nonempty={k for k,v in prev.items() if v}
new=[k for k,v in cur.items() if v and k not in prev_nonempty]
print('new papers:', len(new))
with open('new_extract.txt','w') as o:
    for k in new:
        o.write(f'===== {k} =====\n'+''.join(cur[k]))
import os; print(os.path.getsize('new_extract.txt'))
PY

